from pathlib import Path

ROOT=Path('.')

def read(path): return (ROOT/path).read_text()
def write(path,s): (ROOT/path).write_text(s)
def replace_once(path,old,new,label):
    s=read(path)
    if old not in s: raise SystemExit(f'{label}: anchor missing: {path}')
    if s.count(old)!=1: raise SystemExit(f'{label}: expected one anchor, got {s.count(old)}')
    write(path,s.replace(old,new,1))
def insert_once(path,anchor,addition,label,before=False):
    s=read(path)
    if addition in s: return
    if anchor not in s: raise SystemExit(f'{label}: anchor missing: {path}')
    if s.count(anchor)!=1: raise SystemExit(f'{label}: expected one anchor, got {s.count(anchor)}')
    write(path,s.replace(anchor,(addition+anchor) if before else (anchor+addition),1))

