admin_helpers='''\nlet legacyTestCleanupStarted=false;\nasync function deleteDocsByCampaign(collection,campaignId){const snap=await db.collection(collection).where('campaignId','==',campaignId).get();for(let x=0;x<snap.docs.length;x+=350){const b=db.batch();snap.docs.slice(x,x+350).forEach(d=>b.delete(d.ref));await b.commit()}return snap.size}\nasync function cleanupLegacyTestCampaigns(force=false){if(legacyTestCleanupStarted&&!force)return;legacyTestCleanupStarted=true;const legacy=state.campaigns.filter(c=>c.isTest&&c.testScope!=='full_inventory');if(!legacy.length)return;const ids=new Set(legacy.map(c=>c.id));if(ids.has(String(state.control?.activeCampaignId||'')))await db.collection('system_controls').doc('stocktake_feature').set({enabled:false,accessMode:'none',activeCampaignId:'',updatedAt:firebase.firestore.FieldValue.serverTimestamp(),updatedBy:'مهند'},{merge:true});for(const c of legacy){await deleteDocsByCampaign('stocktake_items',c.id);await deleteDocsByCampaign('stocktake_teams',c.id);await deleteDocsByCampaign('stocktake_audit',c.id);await db.collection('stocktake_campaigns').doc(c.id).delete()}if(state.campaign&&ids.has(state.campaign.id)){state.campaign=null;selectedId=''}toast(`تم تنظيف ${legacy.length} تجربة جرد قديمة`)}\nfunction openAccountingAccess(){const c=state.accountingControl||{};$('#accountingAccessMode').value=c.enabled?(c.accessMode||'selected'):'none';const selected=new Set(c.allowedEmployeeIds||[]);$('#accountingMembers').innerHTML=state.employees.map(e=>`<label><input type="checkbox" data-accounting-member="${e.id}" ${selected.has(e.id)?'checked':''}><span>${esc(empName(e))}</span></label>`).join('')||'<div class="muted">لا توجد حسابات موظفين متاحة.</div>';syncAccountingMembersVisibility();$('#accountingAccessModal').classList.add('open')}\nfunction syncAccountingMembersVisibility(){const mode=$('#accountingAccessMode')?.value||'none';if($('#accountingMembersWrap'))$('#accountingMembersWrap').style.display=mode==='selected'?'block':'none'}\n$('#accountingAccessMode').onchange=syncAccountingMembersVisibility;$('#accountingAccessCancel').onclick=()=>$('#accountingAccessModal').classList.remove('open');$('#accountingAccessModal').onclick=e=>{if(e.target.id==='accountingAccessModal')$('#accountingAccessCancel').click()};$('#accountingAccessSave').onclick=async()=>{const mode=$('#accountingAccessMode').value,ids=mode==='selected'?[...document.querySelectorAll('[data-accounting-member]:checked')].map(x=>x.dataset.accountingMember):[],names=ids.map(id=>empName(state.employees.find(e=>e.id===id))).filter(Boolean);if(mode==='selected'&&!ids.length)return toast('اختر موظفًا واحدًا على الأقل');const payload={enabled:mode!=='none',accessMode:mode==='none'?'none':mode,allowedEmployeeIds:ids,allowedEmployeeNames:names,updatedAt:firebase.firestore.FieldValue.serverTimestamp(),updatedBy:'مهند'};try{await db.collection('system_controls').doc('stocktake_accounting_view').set(payload,{merge:true});state.accountingControl={...state.accountingControl,...payload};$('#accountingAccessCancel').click();toast(mode==='none'?'تم إخفاء متابعة الجرد':mode==='all'?'متابعة الجرد متاحة لجميع الموظفين':`متابعة الجرد متاحة لـ ${ids.length} موظف`)}catch(e){console.error(e);toast('تعذر حفظ صلاحية المحاسب')}};\n'''
