shortcut_patch='''\n    const accountingShortcut=`const StocktakeAccountingShortcut = () => {\n    const [visible,setVisible]=useState(false);\n    useEffect(()=>{\n        const employeeId=String(localStorage.getItem('inventory_employee_id_v2')||'').trim();\n        const employeeName=String(localStorage.getItem('inventory_user_name_v2')||'').trim();\n        const normalizeAccessName=value=>String(value||'').toLowerCase().replace(/[\\u064B-\\u065F\\u0670]/g,'').replace(/\\u0640/g,'').replace(/[أإآٱ]/g,'ا').replace(/[ىئ]/g,'ي').replace(/ؤ/g,'و').replace(/ة/g,'ه').replace(/\\s+/g,' ').trim();\n        const unsub=firebase.firestore().collection('system_controls').doc('stocktake_accounting_view').onSnapshot(doc=>{\n            const c=doc.exists?doc.data():{};const ids=new Set(c.allowedEmployeeIds||[]),names=new Set((c.allowedEmployeeNames||[]).map(normalizeAccessName));\n            setVisible(Boolean(c.enabled&&(c.accessMode==='all'||(c.accessMode==='selected'&&(ids.has(employeeId)||names.has(normalizeAccessName(employeeName)))))));\n        },()=>setVisible(false));\n        return()=>{try{unsub()}catch{}};\n    },[]);\n    if(!visible)return null;\n    return <button type=\"button\" onClick={()=>{location.href='./stocktake-accountant.html?v=56.12'}} className=\"fixed left-10 z-[190] h-44 px-14 rounded-14 bg-primary text-white text-[11px] font-bold shadow-lift border border-primary active:scale-[.98]\" style={{bottom:'max(76px, calc(env(safe-area-inset-bottom) + 68px))'}} aria-label=\"متابعة الجرد\">متابعة الجرد</button>;\n};\n\n`;\n    const accountingAppMarker='const App = () => {';\n    if(!html.includes(accountingAppMarker))throw new Error('V56_12_ACCOUNTING_APP_MARKER');\n    html=html.replace(accountingAppMarker,accountingShortcut+accountingAppMarker);\n'''
